package glitch

import data.glitch_lib

weak_encryption_algorithms := {"DES", "3DES", "TDES", "RC2", "RC4", "Blowfish", "IDEA", "SEED", "CAST", "TEA", "XTEA", "MD5", "SHA1", "SHA-1", "RIPEMD", "MD4", "MD2"}

weak_tls_versions := {"TLSv1.0", "TLSv1.1", "SSLv3", "SSLv2", "TLS1.0", "TLS1.1"}

weak_cipher_indicators := {"NULL", "EXPORT", "DES", "RC4", "3DES", "CBC", "ECB"}

weak_key_size_patterns := {"56-bit", "64-bit", "80-bit", "1024-bit", "512-bit"}

encryption_related_attrs := {"encryption_algorithm", "algorithm", "cipher", "cipher_suite", "tls_version", "min_tls_version", "ssl_policy", "protocol", "certificate_algorithm", "signing_algorithm", "key_spec", "kms_key_spec", "sse_algorithm", "key_size", "key_length", "bits"}

is_weak_algorithm(value) {
    value.ir_type == "String"
    alg := lower(value.value)
    weak := weak_encryption_algorithms[_]
    contains(alg, lower(weak))
}

is_weak_tls_version(value) {
    value.ir_type == "String"
    ver := value.value
    weak_tls_versions[ver]
}

is_weak_cipher(value) {
    value.ir_type == "String"
    cipher := upper(value.value)
    weak := weak_cipher_indicators[_]
    contains(cipher, weak)
}

is_weak_key_size(value) {
    value.ir_type == "String"
    size := lower(value.value)
    weak := weak_key_size_patterns[_]
    contains(size, weak)
}

is_weak_key_size(value) {
    value.ir_type == "Integer"
    value.value <= 1024
}

check_value_for_weak_crypto(node) {
    is_weak_algorithm(node)
} else {
    is_weak_tls_version(node)
} else {
    is_weak_cipher(node)
} else {
    is_weak_key_size(node)
}

find_weak_crypto_in_expr(node) {
    check_value_for_weak_crypto(node)
} else {
    node.ir_type == "Array"
    arr_elem := node.value[_]
    find_weak_crypto_in_expr(arr_elem)
} else {
    node.ir_type == "Hash"
    hash_val := node.value[_]
    find_weak_crypto_in_expr(hash_val)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr_name_lower := lower(attr.name)
    encryption_related_attrs[attr_name_lower]

    find_weak_crypto_in_expr(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a Broken or Risky Cryptographic Algorithm - Avoid using weak or deprecated cryptographic algorithms, protocols, or key sizes. (CWE-327)"
    }
}

