weak_tls_versions := {"TLSv1.0", "TLSv1.1", "SSLv3", "SSLv2", "TLS1.0", "TLS1.1", "TLSv1", "TLS1"}

weak_cipher_indicators := {"NULL", "EXPORT", "DES", "RC4", "3DES", "CBC-", "-CBC", "_CBC", "ECB-", "-ECB", "_ECB"}

weak_key_size_patterns := {"56-bit", "64-bit", "80-bit", "1024-bit", "512-bit"}

encryption_attr_names := {"encryption", "algorithm", "cipher", "cipher_suite", "cipher_suites", "tls_version", "min_tls_version", "ssl_policy", "protocol", "certificate_algorithm", "signing_algorithm", "key_spec", "kms_key_spec", "sse_algorithm", "key_size", "key_length", "bits", "encrypt", "hash", "crypto"}

custom_crypto_indicators := {"custom_encryption", "proprietary_crypto", "legacy_crypto_compat", "obfuscation", "XOR", "ROT13", "custom_crypto", "xor", "rot13"}

weak_hash_functions := {"md5", "sha1"}

is_encryption_related_attr(name) {
    attr := encryption_attr_names[_]
    contains(lower(name), attr)
}

is_weak_algorithm(str) {
    upper_str := upper(str)
    weak := weak_encryption_algorithms[_]
    upper_str == weak
}

is_weak_algorithm(str) {
    upper_str := upper(str)
    weak := weak_encryption_algorithms[_]
    contains(upper_str, weak)
    # Ensure it's not a substring of a larger word unless it's clearly a match
    not is_exception(upper_str)
}

is_exception(str) {
    # Avoid false positives like "document" containing "MD"
    str == "DOCUMENT"
}

is_weak_tls_version(str) {
    weak_tls_versions[str]
}

is_weak_cipher(str) {
    upper_str := upper(str)
    weak := weak_cipher_indicators[_]
    contains(upper_str, weak)
}

is_weak_key_size(str) {
    lower_str := lower(str)
    weak := weak_key_size_patterns[_]
    contains(lower_str, weak)
}

check_string_for_weak_crypto(str) {
    is_weak_algorithm(str)
} else {
    is_weak_tls_version(str)
} else {
    is_weak_cipher(str)
} else {
    is_weak_key_size(str)
}

check_function_call_name(name) {
    lower_name := lower(name)
    func := weak_hash_functions[_]
    lower_name == func
} else {
    lower_name := lower(name)
    contains(lower_name, "md5")
    not contains(lower_name, "hmac")
}

extract_and_check_values(node) {
    node.ir_type == "String"
    check_string_for_weak_crypto(node.value)
} else {
    node.ir_type == "FunctionCall"
    check_function_call_name(node.name)
} else {
    node.ir_type == "VariableReference"
    check_string_for_weak_crypto(node.value)
} else {
    node.ir_type == "Array"
    item := node.value[_]
    item.ir_type == "String"
    check_string_for_weak_crypto(item.value)
} else {
    node.ir_type == "Hash"
    item := node.value[_]
    check_hash_item(item)
}

check_hash_item(item) {
    # Check key for crypto-related names
    item.key.ir_type == "String"
    is_encryption_related_attr(item.key.value)
    item.value.ir_type == "String"
    check_string_for_weak_crypto(item.value)
} else {
    # Check value recursively
    item.value.ir_type == "Hash"
    inner := item.value.value[_]
    check_hash_item(inner)
} else {
    # Check value directly
    item.value.ir_type == "String"
    check_string_for_weak_crypto(item.value)
}

check_nested_hash_for_weak_crypto(node) {
    node.ir_type == "Hash"
    item := node.value[_]
    item.key.ir_type == "String"
    is_encryption_related_attr(item.key.value)
    item.value.ir_type == "String"
    check_string_for_weak_crypto(item.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_encryption_related_attr(attr.name)
    extract_and_check_values(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a Broken or Risky Cryptographic Algorithm - Avoid using weak or deprecated cryptographic algorithms, protocols, or key sizes. (CWE-327)"
    }
}

