weak_tls_versions := {"TLSv1.0", "TLSv1.1", "SSLv3", "SSLv2", "TLS1.0", "TLS1.1", "TLSv1", "TLS1", "1.0", "1.1"}

weak_cipher_indicators := {"NULL", "EXPORT", "DES", "RC4", "3DES", "CBC-", "-CBC", "_CBC", "ECB-", "-ECB", "_ECB"}

weak_key_size_patterns := {"56-bit", "64-bit", "80-bit", "1024-bit", "512-bit"}

encryption_attr_names := {"encryption", "algorithm", "cipher", "cipher_suite", "cipher_suites", "tls_version", "min_tls_version", "ssl_policy", "protocol", "certificate_algorithm", "signing_algorithm", "key_spec", "kms_key_spec", "sse_algorithm", "key_size", "key_length", "bits", "encrypt", "hash", "crypto", "password", "passwd", "pass"}

custom_crypto_indicators := {"custom_encryption", "proprietary_crypto", "legacy_crypto_compat", "obfuscation", "XOR", "ROT13", "custom_crypto"}

weak_hash_patterns := {"md5", "sha1", "sha-1"}

is_encryption_related_attr(name) {
    lower_name := lower(name)
    attr := encryption_attr_names[_]
    contains(lower_name, attr)
}

is_weak_algorithm(str) {
    upper_str := upper(str)
    weak := weak_encryption_algorithms[_]
    upper_str == weak
} else {
    upper_str := upper(str)
    weak := weak_encryption_algorithms[_]
    contains(upper_str, weak)
    not contains(upper_str, "DOCUMENT")
}

is_weak_tls_version(str) {
    weak_tls_versions[str]
}

is_weak_cipher(str) {
    upper_str := upper(str)
    weak := weak_cipher_indicators[_]
    contains(upper_str, weak)
}

is_weak_key_size(str) {
    lower_str := lower(str)
    weak := weak_key_size_patterns[_]
    contains(lower_str, weak)
}

is_weak_hash_in_string(str) {
    lower_str := lower(str)
    pattern := weak_hash_patterns[_]
    contains(lower_str, pattern)
}

check_string_for_weak_crypto(str) {
    is_weak_algorithm(str)
} else {
    is_weak_tls_version(str)
} else {
    is_weak_cipher(str)
} else {
    is_weak_key_size(str)
} else {
    is_weak_hash_in_string(str)
}

check_function_name(name) {
    lower_name := lower(name)
    pattern := weak_hash_patterns[_]
    contains(lower_name, pattern)
} else {
    lower_name := lower(name)
    contains(lower_name, "md5")
    not contains(lower_name, "hmac")
} else {
    lower_name := lower(name)
    contains(lower_name, "sha1")
    not contains(lower_name, "hmac")
}

check_value_leaf(node) {
    node.ir_type == "String"
    check_string_for_weak_crypto(node.value)
} else {
    node.ir_type == "FunctionCall"
    check_function_name(node.name)
} else {
    node.ir_type == "MethodCall"
    check_function_name(node.method)
} else {
    node.ir_type == "VariableReference"
    check_string_for_weak_crypto(node.value)
}

check_value_recursive(node, depth) {
    depth > 0
    check_value_leaf(node)
} else {
    depth > 0
    node.ir_type == "Array"
    item := node.value[_]
    check_value_recursive(item, depth - 1)
} else {
    depth > 0
    node.ir_type == "Hash"
    entry := node.value[_]
    check_hash_entry_recursive(entry, depth - 1)
}

check_hash_entry_recursive(entry, depth) {
    depth > 0
    check_value_leaf(entry.value)
} else {
    depth > 0
    entry.value.ir_type == "Array"
    item := entry.value.value[_]
    check_value_recursive(item, depth - 1)
} else {
    depth > 0
    entry.value.ir_type == "Hash"
    inner_entry := entry.value.value[_]
    check_hash_entry_recursive(inner_entry, depth - 1)
}

check_value_deep(node) {
    check_value_recursive(node, 5)
}

check_attr_value(attr) {
    is_encryption_related_attr(attr.name)
    check_value_deep(attr.value)
}

check_attr_name_weak(attr) {
    attr.value.ir_type == "String"
    val := attr.value.value
    indicator := custom_crypto_indicators[_]
    contains(lower(val), indicator)
}

