weak_encryption_algorithms := {"DES", "3DES", "TDES", "RC2", "RC4", "Blowfish", "IDEA", "SEED", "CAST", "TEA", "XTEA", "MD5", "SHA1", "SHA-1", "RIPEMD", "MD4", "MD2"}

weak_tls_versions := {"TLSv1.0", "TLSv1.1", "SSLv3", "SSLv2", "TLS1.0", "TLS1.1", "TLSv1", "TLS1", "1.0", "1.1"}

weak_cipher_indicators := {"NULL", "EXPORT", "DES", "RC4", "3DES", "CBC", "ECB", "PKCS1V15", "PKCS#1V1.5", "NOPADDING", "NULLPADDING", "MD5_CRYPT", "SHA1_CRYPT"}

weak_key_size_patterns := {"56-bit", "64-bit", "80-bit", "1024-bit", "512-bit"}

encryption_attr_names := {"encryption", "algorithm", "cipher", "cipher_suite", "cipher_suites", "tls_version", "min_tls_version", "ssl_policy", "protocol", "certificate_algorithm", "signing_algorithm", "key_spec", "kms_key_spec", "sse_algorithm", "key_size", "key_length", "bits", "encrypt", "hash", "crypto", "password", "passwd", "pass", "digest", "mac", "hmac"}

password_storage_indicators := {"password", "passwd", "pass", "secret", "credential", "auth", "passwd_md5", "password_md5", "md5_pass", "md5_password", "sha1_pass", "sha1_password"}

custom_crypto_indicators := {"custom_encryption", "proprietary_crypto", "legacy_crypto_compat", "obfuscation", "XOR", "ROT13", "custom_crypto"}

is_encryption_related_attr(name) {
    lower_name := lower(name)
    attr := encryption_attr_names[_]
    contains(lower_name, attr)
}

is_password_storage_attr(name) {
    lower_name := lower(name)
    indicator := password_storage_indicators[_]
    contains(lower_name, indicator)
}

is_weak_algorithm(str) {
    upper_str := upper(str)
    weak := weak_encryption_algorithms[_]
    upper_str == weak
}

is_weak_algorithm(str) {
    upper_str := upper(str)
    weak := weak_encryption_algorithms[_]
    contains(upper_str, weak)
    not contains(upper_str, "DOCUMENT")
}

is_weak_tls_version(str) {
    weak_tls_versions[str]
}

is_weak_cipher(str) {
    upper_str := upper(str)
    weak := weak_cipher_indicators[_]
    contains(upper_str, weak)
}

is_weak_key_size(str) {
    lower_str := lower(str)
    weak := weak_key_size_patterns[_]
    contains(lower_str, weak)
}

check_string_for_weak_crypto(str) {
    is_weak_algorithm(str)
}

