    arg := weak_encryption_algorithms[_]
    contains(lower_name, lower(arg))
}

hash_func_arg_contains_weak(arg) {
    arg.ir_type == "String"
    check_string_for_weak_crypto(arg.value)
}

check_function_call(func_call) {
    func_call.ir_type == "FunctionCall"
    lower_name := lower(func_call.name)
    contains(lower_name, "hash")
    count(func_call.args) > 0
    arg := func_call.args[_]
    hash_func_arg_contains_weak(arg)
}

check_function_call(func_call) {
    func_call.ir_type == "FunctionCall"
    check_function_name(func_call.name)
}

check_leaf_value(node) {
    node.ir_type == "String"
    check_string_for_weak_crypto(node.value)
}

check_leaf_value(node) {
    node.ir_type == "VariableReference"
    check_string_for_weak_crypto(node.value)
}

contains_str(str, substr) {
    contains(lower(str), substr)
}

check_attr_value(attr) {
    is_encryption_related_attr(attr.name)
    check_leaf_value(attr.value)
} else {
    is_encryption_related_attr(attr.name)
    walk_any_value(attr.value)
}

walk_any_value(node) {
    node.ir_type == "Array"
    item := node.value[_]
    walk_any_value(item)
}

walk_any_value(node) {
    node.ir_type == "Hash"
    entry := node.value[_]
    walk_any_value(entry.value)
}

walk_any_value(node) {
    node.ir_type == "FunctionCall"
    check_function_call(node)
}

walk_any_value(node) {
    node.ir_type == "MethodCall"
    check_function_call(node)
}

check_attr_name_weak(attr) {
    attr.value.ir_type == "String"
    val := attr.value.value
    indicator := custom_crypto_indicators[_]
    contains_str(val, indicator)
}

check_attr_name_weak(attr) {
