check_nested_hash_encryption(hash_node) {
    hash_node.ir_type == "Hash"

    has_encrypt_key := {k | 
        entry := hash_node.value[_]
        entry.key.ir_type == "String"
        lower(entry.key.value) == "encrypt"
        k := entry.key.value
    }
    count(has_encrypt_key) > 0

    entry := hash_node.value[_]
    lower(entry.key.value) == "encrypt"
    entry.value.ir_type == "String"
    check_string_for_weak_crypto(entry.value.value)
}

check_nested_hash_in_array(array_node) {
    array_node.ir_type == "Array"
    hash_item := array_node.value[_]
    check_nested_hash_encryption(hash_item)
}

check_deep_attr_value(attr) {
    attr.value.ir_type == "Array"
    check_nested_hash_in_array(attr.value)
} else {
    attr.value.ir_type == "Hash"
    check_nested_hash_encryption(attr.value)
}

